# Let me search all available text files for "1969-July" pattern
import os
import re

for filename in os.listdir('/app/resources'):
    if filename.endswith('.txt') and not filename.startswith('._'):
        filepath = os.path.join('/app/resources', filename)
        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                # Search for July 1969
                if '1969-July' in content or '1969- July' in content or '1969 July' in content:
                    print(f"\nFound in {filename}")
                    # Print some context
                    idx = content.find('1969')
                    if idx != -1:
                        print(content[idx:idx+100])
        except Exception as e:
            print(f"Error reading {filename}: {e}")
